INSERT INTO translations (tenant_id, entity_type, entity_id, field, lang, value) SELECT tenant_id, 'campaign', id, 'title', 'km', title_km FROM campaigns WHERE title_km IS NOT NULL AND trim(title_km) != '' AND EXISTS (SELECT 1 FROM languages WHERE code = 'km') ON CONFLICT DO NOTHING;--> statement-breakpoint
INSERT INTO translations (tenant_id, entity_type, entity_id, field, lang, value) SELECT tenant_id, 'campaign', id, 'blurb', 'km', blurb_km FROM campaigns WHERE blurb_km IS NOT NULL AND trim(blurb_km) != '' AND EXISTS (SELECT 1 FROM languages WHERE code = 'km') ON CONFLICT DO NOTHING;--> statement-breakpoint
INSERT INTO translations (tenant_id, entity_type, entity_id, field, lang, value) SELECT tenant_id, 'campaign', id, 'title', (SELECT COALESCE((SELECT code FROM languages WHERE code = 'en'), (SELECT code FROM languages WHERE is_default = 1 LIMIT 1), 'en')), title FROM campaigns WHERE title IS NOT NULL AND trim(title) != '' ON CONFLICT DO NOTHING;--> statement-breakpoint
INSERT INTO translations (tenant_id, entity_type, entity_id, field, lang, value) SELECT tenant_id, 'campaign', id, 'blurb', (SELECT COALESCE((SELECT code FROM languages WHERE code = 'en'), (SELECT code FROM languages WHERE is_default = 1 LIMIT 1), 'en')), blurb FROM campaigns WHERE blurb IS NOT NULL AND trim(blurb) != '' ON CONFLICT DO NOTHING;--> statement-breakpoint
